use crate::_comparison_tools::bounds_checker::get_validity_flags;
use crate::enums::CaptureMode::GRAMMAR_CAPTURE;
use crate::enums::Layer::{ARRAY_LAYER, OBJECT_LAYER};
use crate::enums::Token::{
